SELECT AVG(icustays.los) AS average_length_of_stay, SUM(CASE WHEN patients.dod IS NOT NULL THEN 1 ELSE 0 END) / NULLIF(COUNT(patients.subject_id), 0) AS in_hospital_mortality_rate FROM admissions JOIN patients ON admissions.subject_id = patients.subject_id JOIN icustays ON admissions.stay_id = icustays.stay_id WHERE admissions.admission_type = 'ACS' AND patients.gender = 'M' AND patients.anchor_age BETWEEN 73 AND 83 AND EXISTS (SELECT 1 FROM labevents WHERE labevents.subject_id = patients.subject_id AND labevents.itemid = 817987 AND labevents.value > 1.5) GROUP BY admissions.hadm_id;